import{_ as a,o,c as t,a7 as r}from"./chunks/framework.FWlv_suP.js";const u=JSON.parse('{"title":"Birthday Buddy Privacy Policy","description":"Official Privacy Policy for Birthday Buddy.","frontmatter":{"title":"Birthday Buddy Privacy Policy","description":"Official Privacy Policy for Birthday Buddy.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"privacy/birthday-buddy.md","filePath":"privacy/birthday-buddy.md"}'),i={name:"privacy/birthday-buddy.md"};function n(s,e,d,c,l,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="privacy-policy-for-birthday-buddy" tabindex="-1">Privacy Policy for Birthday Buddy <a class="header-anchor" href="#privacy-policy-for-birthday-buddy" aria-label="Permalink to &quot;Privacy Policy for Birthday Buddy&quot;">​</a></h1><p><strong>Effective Date:</strong> August 26, 2026<br><strong>Last Updated:</strong> August 26, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Birthday Buddy is a private, offline-first reminder app developed by <strong>Anand Raja</strong>. It helps you remember birthdays, anniversaries, and other occasions. The app does not require an account and does not include advertising, analytics, tracking, or developer-operated cloud sync.</p><h2 id="information-stored-on-your-device" tabindex="-1">Information stored on your device <a class="header-anchor" href="#information-stored-on-your-device" aria-label="Permalink to &quot;Information stored on your device&quot;">​</a></h2><p>Birthday Buddy can store names, photos, birthdays, anniversaries, custom occasions, notes, favourites, reminder settings, contact links, contact-sync choices, theme and privacy preferences, and app-lock settings. Android stores app data locally in SQLite and protected app preferences. The browser version stores app data in browser-local storage such as IndexedDB.</p><p>This information remains on your device unless you explicitly export a backup. The developer does not automatically receive or upload it.</p><h2 id="contacts-and-contact-sync" tabindex="-1">Contacts and contact sync <a class="header-anchor" href="#contacts-and-contact-sync" aria-label="Permalink to &quot;Contacts and contact sync&quot;">​</a></h2><p>You can add a person manually, select an individual contact, or start an optional contact sync. Selecting one contact uses Android&#39;s contact picker. Full contact sync asks for contacts permission and reads only the information needed to prepare a preview, such as a contact lookup identifier, display name, contact photo, birthday, anniversary, and other supported date events.</p><p>Sync is user-initiated, preview-first, and non-destructive. Birthday Buddy does not write to, edit, or delete Android contacts. Contact information is processed on the device and is not sent to the developer. An imported contact photo may be copied into Birthday Buddy&#39;s local data so it remains available in the app. Records you create manually are not overwritten by contact sync, and removing a source contact does not automatically delete an existing Birthday Buddy record.</p><p>If you ignore a contact during sync, a local reference may be retained so the contact stays ignored until you allow it again or clear app data.</p><h2 id="photos-and-camera" tabindex="-1">Photos and camera <a class="header-anchor" href="#photos-and-camera" aria-label="Permalink to &quot;Photos and camera&quot;">​</a></h2><p>You can optionally select a photo or take a new photo for a person. Camera permission is requested only when you choose to take a photo. Selecting an existing image uses Android&#39;s system photo picker and does not require broad access to your photo library. Selected or captured images are copied into app-local data and are not uploaded by Birthday Buddy.</p><h2 id="reminders-and-notifications" tabindex="-1">Reminders and notifications <a class="header-anchor" href="#reminders-and-notifications" aria-label="Permalink to &quot;Reminders and notifications&quot;">​</a></h2><p>Reminders are scheduled and delivered locally on your device. Notification permission is requested when you enable reminder features on Android versions that require it. Lock-screen privacy settings can show full details, a person&#39;s name only, or private wording.</p><p>Android controls notification timing, battery optimization, exact-alarm availability, and lock-screen display. Reboot, wake-lock, vibration, and alarm capabilities may be used only to restore or deliver the local reminders you configured. Birthday Buddy reminders are a convenience and are not guaranteed to arrive at an exact time.</p><h2 id="app-lock-and-biometrics" tabindex="-1">App lock and biometrics <a class="header-anchor" href="#app-lock-and-biometrics" aria-label="Permalink to &quot;App lock and biometrics&quot;">​</a></h2><p>You can optionally protect Birthday Buddy with a PIN. The app stores a salted cryptographic verifier rather than your readable PIN. On Android, sensitive lock material is protected with Android Keystore-backed encryption. In the browser, the verifier remains in browser-local storage.</p><p>After setting a PIN, you may optionally enable biometric unlock. Authentication is performed by Android and the app receives only the authentication result needed to unlock protected app data. Birthday Buddy does not receive or store fingerprints, facial images, or biometric templates.</p><h2 id="backup-and-restore" tabindex="-1">Backup and restore <a class="header-anchor" href="#backup-and-restore" aria-label="Permalink to &quot;Backup and restore&quot;">​</a></h2><p>Backups are created only when you request them. Birthday Buddy encrypts backup contents with AES-GCM using a key derived from the password you provide with PBKDF2-SHA-256. The backup password is not stored by the app or known to the developer and cannot be recovered by the developer. PIN and biometric credentials are not included in backups.</p><p>Exported <code>.ocbackup</code> files are saved to the location you choose and remain outside Birthday Buddy until you delete them. Anyone with the backup file and its password may be able to restore its contents, so keep both secure.</p><h2 id="information-collected-by-the-developer" tabindex="-1">Information collected by the developer <a class="header-anchor" href="#information-collected-by-the-developer" aria-label="Permalink to &quot;Information collected by the developer&quot;">​</a></h2><p>Birthday Buddy has no developer account system, advertising, analytics, tracking SDK, or developer-operated cloud database. The developer does not receive your people, occasions, contacts, photos, notes, reminders, PIN, biometric information, or backup password.</p><p>If you email support, the developer receives only the information you choose to include and uses it to respond. Do not send contact data, personal dates, photos, PINs, passwords, or backup files unless you understand the risk.</p><h2 id="android-permissions" tabindex="-1">Android permissions <a class="header-anchor" href="#android-permissions" aria-label="Permalink to &quot;Android permissions&quot;">​</a></h2><p>Depending on your Android version and the features you use, the installed app may declare or request the following permissions:</p><ul><li><strong><code>android.permission.READ_CONTACTS</code></strong> — requested at runtime only when you start full contact sync, so the app can prepare an on-device import preview. Birthday Buddy does not request <code>WRITE_CONTACTS</code>.</li><li><strong><code>android.permission.CAMERA</code></strong> — requested at runtime only when you choose <strong>Take Photo</strong>.</li><li><strong><code>android.permission.POST_NOTIFICATIONS</code></strong> — requested on supported Android versions so the app can display the local occasion reminders you enable.</li><li><strong><code>android.permission.RECEIVE_BOOT_COMPLETED</code></strong> — allows the local-notification system to restore scheduled reminders after the device restarts.</li><li><strong><code>android.permission.WAKE_LOCK</code></strong> — allows Android to wake briefly when needed to deliver a scheduled local reminder; it is not used for continuous background activity.</li><li><strong><code>android.permission.SCHEDULE_EXACT_ALARM</code></strong> — included by the local-notification library so Android can permit timely local reminders where exact-alarm access is supported. It is not used for tracking or uploading data, and Android may limit or deny exact scheduling.</li><li><strong><code>android.permission.VIBRATE</code></strong> — included by the haptics feature and used for optional interface feedback or notification vibration where supported.</li><li><strong><code>android.permission.USE_BIOMETRIC</code></strong> — used only if you enable biometric unlock after setting a PIN.</li><li><strong><code>android.permission.USE_FINGERPRINT</code></strong> — retained by AndroidX Biometric for compatibility with older Android devices; it serves the same optional unlock purpose.</li><li><strong><code>android.permission.INTERNET</code></strong> — included by the Android web-app container. Birthday Buddy&#39;s personal reminder data is not sent to a developer server; network access may occur when you deliberately open an external web link or use an online distribution or hosting surface.</li></ul><p>The app does not request write access to contacts, call logs, SMS, microphone, location, phone state, calendar, or broad photo/storage access. Android&#39;s system pickers are used for files and existing photos where supported.</p><h2 id="browser-version-and-third-party-services" tabindex="-1">Browser version and third-party services <a class="header-anchor" href="#browser-version-and-third-party-services" aria-label="Permalink to &quot;Browser version and third-party services&quot;">​</a></h2><p>The browser version is hosted on GitHub Pages. When you visit it, GitHub may process ordinary web-request information such as an IP address, browser details, and request logs under its own terms and privacy policy. Birthday Buddy does not add analytics or transmit your locally stored occasion data to GitHub.</p><p>Google Play processes information related to downloading, purchasing, reviewing, or updating Android apps under Google&#39;s own policies. External links you choose to open are governed by the destination&#39;s privacy practices.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and deletion&quot;">​</a></h2><p>Deleting a person or occasion moves it to Birthday Buddy&#39;s local Trash, stops its reminders, and schedules it for permanent deletion after 30 days. You can restore an item before that deadline, permanently delete an individual Trash item, or empty Trash immediately. Expired Trash is purged when the app initializes.</p><p>Clearing the app&#39;s storage, clearing the website&#39;s stored data, or uninstalling the app removes app-local data without waiting for the Trash period. These actions do not remove exported backup files or copies saved elsewhere; delete those separately.</p><p>Because Birthday Buddy does not operate an account or cloud database, there is no server-side profile to delete by email. Detailed instructions are available on the Birthday Buddy Data Deletion page.</p><h2 id="children-s-privacy" tabindex="-1">Children&#39;s privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to &quot;Children&#39;s privacy&quot;">​</a></h2><p>Birthday Buddy is not designed to collect children&#39;s personal information through a developer-operated service. A user may choose to store a child&#39;s birthday locally; that information remains subject to the same on-device practices described above.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to this policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to &quot;Changes to this policy&quot;">​</a></h2><p>This policy may be updated when Birthday Buddy&#39;s features or data practices change. The dates above will be revised when an updated policy is published.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',42)])])}const y=a(i,[["render",n]]);export{u as __pageData,y as default};
